effect.shader:
void main(){
vec2 uv = acScreenNorm;
vec2 uvWork = uv;
float prop = acScreenSize.x / acScreenSize.y;
vec2 m = vec2(centerX, (aspectMode != 0) ? (centerY / prop) : centerY);
if(aspectMode != 0){
uvWork = vec2(uv.x, uv.y / prop);
}
vec2 d = uvWork - m;
float r = length(d);
float k = power * 3.14159265;
float bind;
if(k > 0.0){
bind = length(m);
} else if(k < 0.0){
bind = (prop < 1.0) ? m.x : m.y;
} else {
bind = 1.0;
}
vec2 uv2;
if(k > 0.0){
uv2 = m + normalize(d) * tan(r * k) * bind / tan(bind * k);
} else if(k < 0.0){
float kk = -k * 10.0;
uv2 = m + normalize(d) * atan(r * kk) * bind / atan(kk * bind);
} else {
uv2 = uvWork;
}
if(aspectMode != 0){
uv2 = vec2(uv2.x, uv2.y * prop);
}
vec4 src = texture2DCv(inputImg.texture, clamp(uv2, 0.0, 1.0));
float a = src.a * alpha;
gl_FragColor = vec4(src.rgb, 1.0) * a;
}
